import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"失败代码对照","description":"客户端与管理 OpenAPI Error.code 并集，加上控制台 locales（排除纯前端 NETWORK/HTTP/UNKNOWN）。","frontmatter":{"title":"失败代码对照","description":"客户端与管理 OpenAPI Error.code 并集，加上控制台 locales（排除纯前端 NETWORK/HTTP/UNKNOWN）。"},"headers":[],"relativePath":"faq/errors.md","filePath":"faq/errors.md","lastUpdated":1790057721000}`),a={name:`faq/errors.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="失败代码对照" tabindex="-1">失败代码对照 <a class="header-anchor" href="#失败代码对照" aria-label="Permalink to “失败代码对照”">​</a></h1><p>逻辑只看 <code>error.code</code>。渠道 Token 错误<strong>不进</strong> 403。商店缺 listing <strong>无</strong> JSON <code>code</code>。悬停说明与文档站 <code>ErrorCode</code> 组件同源。</p><table tabindex="0"><thead><tr><th>code</th><th>HTTP（若稳定）</th><th>含义与检查</th></tr></thead><tbody><tr><td><code>PROJECT_NOT_FOUND</code></td><td>404</td><td>项目 UUID/slug/别名未命中或别名过期</td></tr><tr><td><code>VERSION_NOT_FOUND</code></td><td>404</td><td>版本不存在</td></tr><tr><td><code>VERSION_LINE_NOT_FOUND</code></td><td>404</td><td>该版本没有此 os/arch 线</td></tr><tr><td><code>VERSION_NOT_VISIBLE</code></td><td>404/409</td><td>版本对客户端不可见（草稿、未预热或灰度未命中）</td></tr><tr><td><code>VERSION_REVOKED</code></td><td>409</td><td>版本已吊销且无安全回落</td></tr><tr><td><code>NO_SAFE_TARGET</code></td><td>409</td><td>没有安全目标版本</td></tr><tr><td><code>INTERMEDIATE_UNAVAILABLE</code></td><td>409</td><td>中继版本缺失、未就绪、成环或 hop 超过 8 次</td></tr><tr><td><code>MIN_OS_NOT_MET</code></td><td>409</td><td>客户端系统/API 低于当前版本线下限</td></tr><tr><td><code>CHANNEL_CONFLICT</code></td><td>409</td><td>幂等创建时渠道与已有版本不一致</td></tr><tr><td><code>UNAUTHORIZED</code></td><td>401</td><td>未认证或会话过期</td></tr><tr><td><code>FORBIDDEN</code></td><td>403</td><td>权限不足（含项目成员访问 /admins、/geoip、/nodes）</td></tr><tr><td><code>PRECONDITION_FAILED</code></td><td>412</td><td>If-Match / ETag 失败（不是 POST check）</td></tr><tr><td><code>HW_REV_INCOMPATIBLE</code></td><td>409</td><td>硬件代号不在兼容范围</td></tr><tr><td><code>RATE_LIMITED</code></td><td>429</td><td>过频；响应带 Retry-After</td></tr><tr><td><code>CHANGELOG_QUERY_INVALID</code></td><td>400</td><td>changelog 查询非法</td></tr><tr><td><code>NOT_FOUND</code></td><td>404</td><td>通用缺失（含未知包哈希）</td></tr><tr><td><code>NOT_READY</code></td><td>503/400</td><td>服务或 Passkey 未就绪。<code>webauthn_rp_id</code> 或 <code>webauthn_origins</code> 任一为空时 Passkey 接口返回本码（HTTP 503）</td></tr><tr><td><code>INTERNAL_ERROR</code></td><td>500</td><td>服务器内部错误</td></tr><tr><td><code>INVALID_REQUEST</code></td><td>400</td><td>请求体/字段非法（含非 .mmdb、超上限、未知矩阵对、重复 listing）</td></tr><tr><td><code>INVALID_QUERY_PARAM</code></td><td>400</td><td>查询参数非法（含公告 version、未知 changelog 渠道）</td></tr><tr><td><code>ENGINE_MISMATCH</code></td><td>400</td><td>比较引擎与版本标识不匹配</td></tr><tr><td><code>ARTIFACT_REQUIRED</code></td><td>400</td><td>发布被拒绝：没有任何就绪的版本线</td></tr><tr><td><code>CHANNEL_SUFFIX_MISMATCH</code></td><td>400</td><td>SemVer 预发布后缀与渠道不一致；stable 不能用预发布后缀</td></tr><tr><td><code>VERSION_ALREADY_EXISTS</code></td><td>409</td><td>同项目版本号占用</td></tr><tr><td><code>GRAY_NOT_ALLOWED_ON_CRITICAL</code></td><td>400</td><td>关键版本禁止灰度</td></tr><tr><td><code>PACKAGE_TYPE_IMMUTABLE</code></td><td>409</td><td>该平台已有已发布版本线后不能改产物形态</td></tr><tr><td><code>COMPARE_ENGINE_IMMUTABLE</code></td><td>409</td><td>已发布后不能改比较引擎</td></tr><tr><td><code>INVALID_PATH</code></td><td>400</td><td>非法路径</td></tr><tr><td><code>ARTIFACT_IMMUTABLE</code></td><td>409</td><td>已发布产物不可覆盖（先 yank 版本线）</td></tr><tr><td><code>HW_REV_UNKNOWN</code></td><td>400</td><td>未登记硬件代号</td></tr><tr><td><code>DELTA_ALGO_UNSUPPORTED</code></td><td>400</td><td>不支持的差量算法</td></tr><tr><td><code>DELTA_SAME_VERSION</code></td><td>400</td><td>源与目标版本相同</td></tr><tr><td><code>TOTP_RATE_LIMITED</code></td><td>429</td><td>同一 30s 周期 TOTP 次数用尽</td></tr><tr><td><code>UPLOAD_INCOMPLETE</code></td><td>400</td><td>上传未完成，不能发布或标记就绪</td></tr><tr><td><code>CHANNEL_NOT_FOUND</code></td><td>404</td><td>渠道不存在</td></tr><tr><td><code>SYSTEM_CHANNEL</code></td><td>409</td><td>系统渠道 alpha/beta/stable 不可删除</td></tr><tr><td><code>CHECKSUM_MISMATCH</code></td><td>400</td><td>声明 SHA-256 与服务端复算不符</td></tr><tr><td><code>JOB_NOT_FOUND</code></td><td>404</td><td>任务不存在</td></tr><tr><td><code>JOB_FAILED</code></td><td>409/500</td><td>异步任务失败</td></tr><tr><td><code>AUTO_PUBLISH_PENDING</code></td><td>409</td><td>auto_publish_when 尚未全部就绪</td></tr><tr><td><code>ZIP_LAYOUT_INVALID</code></td><td>400</td><td>zip 无法解析为 os/arch/…（缺段、未知标识或含路径穿越）</td></tr><tr><td><code>ADMIN_NOT_FOUND</code></td><td>404</td><td>管理员不存在</td></tr><tr><td><code>USERNAME_TAKEN</code></td><td>409</td><td>用户名占用</td></tr><tr><td><code>LAST_ADMIN</code></td><td>409</td><td>不能删除最后一名管理员</td></tr><tr><td><code>LAST_OWNER</code></td><td>400</td><td>不能移除最后一名拥有者</td></tr><tr><td><code>MEMBER_NOT_FOUND</code></td><td>404</td><td>项目成员不存在</td></tr><tr><td><code>CLIENT_NOT_FOUND</code></td><td>404</td><td>客户端名册行不存在</td></tr><tr><td><code>GEOIP_NOT_FOUND</code></td><td>404</td><td>GeoIP 库不存在</td></tr><tr><td><code>LANGUAGE_TAKEN</code></td><td>409</td><td>语言代码已存在</td></tr><tr><td><code>LANGUAGE_NOT_FOUND</code></td><td>404</td><td>语言不存在</td></tr></tbody></table><p><code>DELTA_SAME_VERSION</code> 来自控制台 locales，管理 OpenAPI <code>Error.code</code> enum 未列入；出现时按「源与目标相同」处理。已排除纯前端 <code>NETWORK_ERROR</code> / <code>HTTP_ERROR</code> / <code>UNKNOWN_ERROR</code>。商店缺 listing <strong>无</strong> JSON <code>code</code>。</p>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};